const rows = Array.isArray($json.list) ? $json.list : [];
const draftOnly = true;
const blockedStatuses = new Set(['unsubscribed', 'bounced', 'complained']);
const textFields = ['company_homepage_name', 'parent_company', 'best_url', 'canonical_domain', 'industry_guess', 'website_content', 'source_urls', 'services_detected', 'locations_detected', 'leadership_or_team_signals', 'contact_info_detected', 'structured_data_detected', 'selected_contact_name', 'selected_contact_title', 'selected_contact_role', 'selected_contact_email', 'selected_contact_linkedin_url', 'validated_email', 'unsubscribe_status', 'email_source'];
const output = [];
for (const row of rows) {
  const normalized = { ...row };
  for (const field of textFields) normalized[field] = String(normalized[field] || '').trim();
  normalized.unsubscribe_status = normalized.unsubscribe_status || 'active';
  normalized.do_not_contact = normalized.do_not_contact === true || String(normalized.do_not_contact).toLowerCase() === 'true';
  const unsub = normalized.unsubscribe_status.toLowerCase();
  if (normalized.do_not_contact) continue;
  if (blockedStatuses.has(unsub)) continue;
  output.push({ json: { ...normalized, draft_only: draftOnly } });
}
return output;

const output = [];
for (const [index, item] of items.entries()) {
  const plan = item.json || {};
  if (!plan.patch || !plan.record) {
    output.push({ json: { ...plan, skip_llm: true } });
    continue;
  }
  const sourceRows = $('Rows To Items').all().map((entry) => entry.json || {});
  const patchId = String(plan.patch?.Id || plan.row_id || '').trim();
  const sourceRow = sourceRows.find((candidate) => String(candidate.Id || '').trim() === patchId) || sourceRows[index] || {};
  const record = plan.record || {};
  const classification = record.classification || {};
  const copyBrief = record.copy_brief || {};
  const row = {
    ...sourceRow,
    Id: plan.patch.Id,
    company_name: sourceRow.company_name || plan.patch.company_name || classification.company_name || '',
    selected_contact_name: sourceRow.selected_contact_name || plan.patch.selected_contact_name || '',
    selected_contact_title: sourceRow.selected_contact_title || plan.patch.selected_contact_title || '',
  };
  const system = 'You write short, evidence-based cold email drafts for RAYN Secure. Use only the copy brief. Return strict JSON only. Do not send emails. Do not invent facts.';
  const user = {
    company_name: row.company_name || plan.row_id || '',
    selected_contact_name: row.selected_contact_name || '',
    selected_contact_email: sourceRow.validated_email || sourceRow.selected_contact_email || '',
    selected_contact_title: row.selected_contact_title || '',
    pressure_type: classification.pressure_type,
    clinic_profile_guess: copyBrief.clinic_profile_guess,
    clinic_profile_phrase: copyBrief.clinic_profile_phrase,
    clinic_structure_guess: copyBrief.clinic_structure_guess,
    clinic_structure_confidence: copyBrief.clinic_structure_confidence,
    primary_service_summary: copyBrief.primary_service_summary,
    company_profile_summary: copyBrief.company_profile_summary,
    primary_services_summary: copyBrief.primary_services_summary,
    locations_summary: copyBrief.locations_summary,
    team_structure_summary: copyBrief.team_structure_summary,
    personal_data_handled_guess: copyBrief.personal_data_handled_guess,
    sensitive_data_examples: copyBrief.sensitive_data_examples,
    data_systems_likely: copyBrief.data_systems_likely,
    regulatory_pressure_summary: copyBrief.regulatory_pressure_summary,
    hia_obligation_angle: copyBrief.hia_obligation_angle,
    pdpa_obligation_angle: copyBrief.pdpa_obligation_angle,
    customer_trust_angle: copyBrief.customer_trust_angle,
    deadline_or_timeline_angle: copyBrief.deadline_or_timeline_angle,
    funding_claim_line: copyBrief.funding_route_summary || plan.patch.funding_claim_line,
    funding_claim_safe: copyBrief.funding_claim_safe,
    email_3_mode: copyBrief.email_3_mode || plan.patch.email_3_mode || 'value_fallback',
    email_personalisation_signal: copyBrief.prospect_facing_signal || copyBrief.email_personalisation_signal,
    email_problem_statement: copyBrief.email_problem_statement,
    email_mechanism_statement: copyBrief.email_mechanism_statement,
    email_asset_offer: copyBrief.email_asset_offer,
    email_cta: copyBrief.email_cta,
    email_angle_reason: copyBrief.email_angle_reason,
    rules: [
      'Use the copy brief facts only. Do not invent facts.',
      'If selected_contact_name is present, use Hi {{first_name}},. If selected_contact_name is blank, use Hello team,. Do not invent names.',
      'Email 1 must be exactly four short blocks after greeting: Noticed {{email_personalisation_signal}}, then email_problem_statement, then email_mechanism_statement, then email_cta.',
      'For HIA rows, Email 1 must include clinic_profile_phrase through the personalisation signal.',
      'Do not merge pressure text into the Noticed sentence. The Noticed sentence is only the concrete company signal.',
      'Email 1 must feel like a researched note and must not start with generic noticed your company wording.',
