      'If email_3_mode is value_fallback, Email 3 must not mention funding and should use the checklist/evidence fallback angle.',
      'Do not use prospect-facing HIA batch wording: Batch 1, Batch 2, Batch 3, Sep 2027, Sep 2028, Mar 2030, or HIA window.',
      'For HIA rows, say HIA readiness is becoming more urgent for healthcare providers instead of naming batches or dates.',
      'Funding Email 3 must include: The useful first step is confirming whether the route applies before spending time on readiness work.',
      'Email 4 closes the loop and references email_asset_offer.',
      'Do not say if you are an SME or if you are an NPO.',
      'Do not say eligible SMEs and NPOs may.',
      'Do not claim guaranteed funding.',
      'Do not say Cyber Essentials makes the company PDPA compliant.',
      'Do not say Cyber Essentials completes HIA compliance.',
      'Keep Email 1 <= 85 words, Email 2 <= 80, Email 3 <= 95, Email 4 <= 55.',
      'Use one tiny CTA per email.'
    ],
    return_shape: {
      email_1: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_2: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_3: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_4: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      evidence_used: [],
      claims_avoided: [],
      quality_notes: []
    }
  };
  output.push({
    json: {
      row: row,
      planner_result: plan,
      body: {
        model: 'x-ai/grok-4.3',
        temperature: 0.2,
        max_tokens: 1800,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: JSON.stringify(user) }
        ],
        response_format: { type: 'json_object' }
      }
    }
  });
}
return output;

const output = [];
for (let index = 0; index < items.length; index++) {
  const response = items[index].json || {};
  const prepared = $('Prepare OpenRouter Email Draft').all()[index]?.json || {};
  output.push({ json: { ...prepared, openrouter_response: response } });
}
return output;

function wordCount(text) {
  return String(text || '').match(/\b[\w'-]+\b/g)?.length || 0;
}
function parseFlags(value) {
  try { return Array.isArray(value) ? value : JSON.parse(value || '[]'); } catch (error) { return value ? [String(value)] : []; }
}
function auditFromPatch(patch, prior = {}) {
  return {
    row_id: patch.Id || prior.row_id || '',
    company_name: prior.company_name || patch.company_name || '',
    pressure_type: patch.pressure_type || prior.pressure_type || '',
    hia_service_type_guess: patch.hia_service_type_guess || prior.hia_service_type_guess || '',
    hia_timeline_batch_guess: patch.hia_timeline_batch_guess || prior.hia_timeline_batch_guess || '',
    funding_status: patch.funding_status || prior.funding_status || '',
    automation_decision: patch.automation_decision || prior.automation_decision || '',
    automation_decision_reason: patch.automation_decision_reason || prior.automation_decision_reason || '',
    automation_blockers_json: parseFlags(patch.automation_blockers_json || prior.automation_blockers_json),
    automation_advisory_flags_json: parseFlags(patch.automation_advisory_flags_json || prior.automation_advisory_flags_json),
    contact_send_mode: patch.contact_send_mode || prior.contact_send_mode || '',
    contact_identity_confidence: patch.contact_identity_confidence || prior.contact_identity_confidence || '',
    email_3_mode: patch.email_3_mode || prior.email_3_mode || '',
    enrichment_quality_score: patch.enrichment_quality_score || prior.enrichment_quality_score || 0,
    enrichment_quality_flags: parseFlags(patch.enrichment_quality_flags || prior.enrichment_quality_flags),
    copy_brief_quality_score: patch.copy_brief_quality_score || prior.copy_brief_quality_score || 0,
    copy_brief_quality_flags: parseFlags(patch.copy_brief_quality_flags || prior.copy_brief_quality_flags),
    severe_email_flags: parseFlags(patch.severe_email_flags || prior.severe_email_flags),
    final_send_gate_passed: patch.final_send_gate_passed || prior.final_send_gate_passed || false,
    email_quality_flags: parseFlags(patch.email_quality_flags || prior.email_quality_flags),
    email_1_subject: patch.email_1_subject || prior.email_1_subject || '',
    email_1_body: patch.email_1_body || prior.email_1_body || '',
    email_2_subject: patch.email_2_subject || prior.email_2_subject || '',
    email_2_body: patch.email_2_body || prior.email_2_body || '',
    email_3_subject: patch.email_3_subject || prior.email_3_subject || '',
    email_3_body: patch.email_3_body || prior.email_3_body || '',
    email_4_subject: patch.email_4_subject || prior.email_4_subject || '',
    email_4_body: patch.email_4_body || prior.email_4_body || '',
  };
}
function fundingGreeting(patch) {
  const company = String(patch.company_name || '').trim();
  return company ? `Hi ${company} team,` : 'Hi team,';
}
function ensureFundingClaim(patch) {
  if (patch.automation_decision !== 'auto_send_eligible') return patch;
  if (patch.pressure_type === 'not_ready') return patch;
  if (patch.email_3_mode && patch.email_3_mode !== 'funding') return patch;
  const claim = String(patch.funding_claim_line || '').trim();
  if (!claim) return patch;
  const body = String(patch.email_3_body || '');
  const usefulLine = 'The useful first step is confirming whether the route applies before spending time on readiness work.';
  const caveatCount = (body.toLowerCase().match(/subject to programme confirmation/g) || []).length;
  if (body.includes(claim) && caveatCount <= 1 && body.toLowerCase().includes(usefulLine.toLowerCase())) return patch;
  const caveat = claim.toLowerCase().includes('subject to programme confirmation') ? [] : ['', 'This is subject to programme confirmation.'];
  const replacement = [fundingGreeting(patch), '', claim, ...caveat, '', usefulLine, '', 'Should I send the route summary?', '', 'Best,', 'SK', 'RAYN Secure'].join('\n');
  let flags = [];
  try { flags = JSON.parse(patch.email_quality_flags || '[]'); } catch (error) { flags = []; }
  flags = flags.filter((flag) => flag !== 'email_3_missing_funding_claim_line');
  let sequenceJson = patch.email_sequence_json;
  try {
    const sequence = JSON.parse(patch.email_sequence_json || '{}');
    if (sequence.email_3) {
      sequence.email_3.body = replacement;
      sequence.email_3.word_count = wordCount(replacement);
      sequenceJson = JSON.stringify(sequence);
    }
  } catch (error) {}
  return { ...patch, email_3_body: replacement, email_sequence_json: sequenceJson, email_quality_flags: JSON.stringify(flags) };
}
const patches = [];
const audits = [];
const errors = [];
for (const item of items) {
  const body = item.json || {};
  if (body.patch && body.patch.Id) {
    const patch = ensureFundingClaim(body.patch);
    patches.push(patch);
    audits.push(auditFromPatch(patch, body.audit_report || {}));
  } else {
    errors.push({ row_id: body.row_id || '', error: body.error || 'missing_patch' });
  }
}
return [{ json: { patches, audits, errors, count: patches.length } }];
